func (r *OrderRepository) Save(ctx context.Context, order *model.Order) error {
    tx, err := r.db.BeginTx(ctx, nil)
    if err != nil {
        return err
    }
    defer tx.Rollback()

    if err := insertOrder(ctx, tx, order); err != nil {
        return err
    }
    if err := insertOrderLines(ctx, tx, order.Lines()); err != nil {
        return err
    }
    return tx.Commit()
}
```

